UPDATE testimonials SET client_name = 'Анна М.', city = 'Москва', text = 'Обратились с проблемой задержки речевого развития у сына (3 года). После 4 месяцев занятий результаты превзошли все ожидания! Ребёнок начал говорить фразами, улучшилось внимание. Огромная благодарность за профессионализм и терпение!', rating = 5 WHERE id = 1;
UPDATE testimonials SET client_name = 'Елена К.', city = 'Санкт-Петербург', text = 'Работаем уже полгода с диагнозом РАС. Дочка стала более контактной, появился зрительный контакт, снизилась тревожность. Специалист находит подход к ребёнку, всегда даёт подробные рекомендации для работы дома.', rating = 5 WHERE id = 2;
UPDATE testimonials SET client_name = 'Мария С.', city = 'Казань', text = 'Сыну 5 лет, диагноз ЗПРР. Занимаемся 8 месяцев. Динамика потрясающая: улучшилась координация, речь стала более развёрнутой, появился интерес к обучению. Рекомендую всем, кто ищет грамотного специалиста!', rating = 5 WHERE id = 3;
UPDATE testimonials SET client_name = 'Ольга Д.', city = 'Екатеринбург', text = 'Очень благодарны за помощь! Дочка с синдромом Дауна стала более самостоятельной, улучшилась мелкая моторика и внимание. Занятия проходят в комфортной обстановке, ребёнок всегда идёт с удовольствием.', rating = 5 WHERE id = 4;